@if (!src) {
  <button ngsButton="outlined" ngsUploadTrigger
          accept="image/png,image/jpeg" (fileSelected)="onImageSelected($event)">Select a local image</button>
} @else {
  <ngs-thumbnail-maker #thumbnailMaker="ngsThumbnailMaker" [src]="src"
                       class="border border-muted  rounded-xl" />
  <div class="mt-10">
    <button ngsButton="filled" (click)="makeThumbnail(thumbnailMaker)">Make thumbnail</button>
  </div>
  @if (thumbnail) {
    <div class="mt-2 flex items-start gap-10 flex-wrap">
      <img [src]="thumbnail" alt="" class="border border-muted ">
      <img [src]="thumbnail" alt="" class="border border-muted  rounded-xl size-40">
      <img [src]="thumbnail" alt="" class="border border-muted  rounded-full size-40">
    </div>
  }
}
